import{z as p,x as B,o as r,c as A,q as s,j as n,D as l,d as t,s as E,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"椭圆曲线群","description":"","frontmatter":{"title":"椭圆曲线群","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/elliptic-curve-group.md","filePath":"cs/elliptic-curve-group.md","lastUpdated":1791413859000}'),d={name:"cs/elliptic-curve-group.md"};function m(h,a,P,D,u,c){const i=B("Mermaid");return r(),A("div",null,[a[2]||(a[2]=s('<h1 id="椭圆曲线群" tabindex="-1">椭圆曲线群 <a class="header-anchor" href="#椭圆曲线群" aria-label="Permalink to &quot;椭圆曲线群&quot;">​</a></h1><div class="epigraph"><p>域上非奇异三次曲线的点，加上无穷远点，用割线–切线定义加法，构成 Abel 群；DLP 在此群上目前比 $\\mathbb{F}_p$ 更硬，故密钥更短。</p><footer>—— 据 Silverman, The Arithmetic of Elliptic Curves；Hankerson, Menezes and Vanstone 整理</footer></div><p>上一课<a href="/cs/prime-generation">素数生成</a> 给出 \\(\\mathbb{F}_p\\)。缺口是 <strong>ECC 群</strong>：点集 \\(E(\\mathbb{F}_q)\\)，\\(\\mathcal{O}\\) 为单位，弦切法为加。本课直觉与阶，不写 TLS 曲线清单。主干 DH 的报文形状可原样搬到 \\(P\\mapsto [k]P\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>仿射方程 \\(y^2=x^3+Ax+B\\)（特征 \\(\\ne 2,3\\)），判别式非零。两点连线交第三点，再对 \\(x\\) 轴反射，定义为和。切线处理倍点。\\(\\mathcal{O}\\) 是竖直线的「无穷」。结合律不显然，本课承认。Hasse：\\(|\\#E-(q+1)|\\le 2\\sqrt q\\)。选阶为大素，或大素子群，防 Pohlig–Hellman。</p><p><span class="marginnote">为什么取反射？割线法的隐藏约束是「三点之和为零」：P+Q+R=O，于是 P+Q = −R，而曲线上「取负」恰好定义为对 x 轴反射。无穷远点 O 则充当加法的「零」：任何点加 O 还是自己，竖直线上互为反射的两点相加就得它。</span></p><p>标量乘 \\([k]P\\) 用倍加，对标快速幂。DLP：已知 \\(P,[k]P\\) 求 \\(k\\)。无通用指标演算，故 256 比特曲线对标 3072 比特有限域（NIST 量级，点名）。</p><p><span class="marginnote">数字实例：Hasse 定理说点数 #E 与 q+1 相差不超过 2√q，取 q 约 2^256 时点数也在 256 比特量级。还要求群阶本身是大素数——否则阶能拆成小素数之积，Pohlig–Hellman 就能「把大难题拆成一堆小难题」各个击破。</span></p><h3 id="不是圆锥曲线插值" tabindex="-1">不是圆锥曲线插值 <a class="header-anchor" href="#不是圆锥曲线插值" aria-label="Permalink to &quot;不是圆锥曲线插值&quot;">​</a></h3><p>「椭圆」来自椭圆积分，不是椭圆形状。与率失真、编码无关。</p><p><span class="marginnote">Silverman 算术。HMV 密码学椭圆曲线。Miller 的 pairing 点名不写。扭曲线、异常曲线是不安全族，选曲线要避开，本课不列 CVE。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在小素域上画几个点，演示 \\(P+(-P)=\\mathcal{O}\\)。对照 \\(\\mathbb{F}_p^\\times\\)：运算换成点加，困难问题仍是 DLP。指出：生成元是基点 \\(G\\)，公开参数含曲线与 \\(G\\)、阶 \\(n\\)。</p>',13)),(r(),n(o,null,{default:l(()=>[E(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20CRV%5B%22%E4%B8%89%E6%AC%A1%E6%9B%B2%E7%BA%BF%20E%22%5D%20--%3E%20PTS%5B%22%E7%82%B9%20%2B%20O%22%5D%0A%20%20PTS%20--%3E%20ADD%5B%22%E5%BC%A6%E5%88%87%E5%8A%A0%E6%B3%95%22%5D%0A%20%20ADD%20--%3E%20DLP%5B%22%E6%A0%87%E9%87%8F%E4%B9%98%E6%98%93%20%2F%20DLP%20%E9%9A%BE%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"ECC 把 DH、ECDSA 的群换掉，不改协议逻辑。量子 Shor 对 ECC DLP 同样有效（BQP 课）。后量子不在这条曲线上找，下一课格。本课是经典公钥群的最后一站。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"常见误区：以为「椭圆曲线」是长得像椭圆的曲线。名字来自椭圆积分——历史上计算椭圆周长时冒出来的那类积分；曲线本身是 \\(y^2=x^3+Ax+B\\) 这样的三次曲线，画出来和椭圆毫无关系。")],-1)),a[6]||(a[6]=e("p",null,"几何上 P+Q 到底怎么一步步算出来？",-1)),(r(),n(o,null,{default:l(()=>[E(i,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%82%B9%20P%22%5D%20--%3E%20L%5B%22%E8%BF%87%20P%E3%80%81Q%20%E7%94%BB%E4%B8%80%E6%9D%A1%E7%9B%B4%E7%BA%BF%22%5D%0A%20%20Q%5B%22%E7%82%B9%20Q%22%5D%20--%3E%20L%0A%20%20L%20--%3E%20T%7B%22%E4%B8%8E%E6%9B%B2%E7%BA%BF%E7%9A%84%E7%AC%AC%E4%B8%89%E4%B8%AA%E4%BA%A4%E7%82%B9%E5%9C%A8%E5%93%AA%3F%22%7D%0A%20%20T%20--%3E%7C%22%E6%9C%89%E9%99%90%E7%82%B9%20R%22%7C%20REF%5B%22R%20%E5%85%B3%E4%BA%8E%20x%20%E8%BD%B4%E5%8F%8D%E5%B0%84%22%5D%0A%20%20REF%20--%3E%20SUM%5B%22P%2BQ%20%3D%20%E2%88%92R%22%5D%0A%20%20T%20--%3E%7C%22P%E3%80%81Q%20%E7%AB%96%E7%9B%B4%E5%AF%B9%E9%BD%90%22%7C%20INF%5B%22%E7%AC%AC%E4%B8%89%E4%B8%AA%E4%BA%A4%E7%82%B9%E6%98%AF%E6%97%A0%E7%A9%B7%E8%BF%9C%20O%22%5D%0A%20%20INF%20--%3E%20SUM%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p>实现：常数时间标量乘、点压缩，属工程，点名。</p><p>点加公式：斜率 \\(\\lambda=(y_2-y_1)/(x_2-x_1)\\) 或切线 \\((3x^2+A)/2y\\)，再 \\(x_3=\\lambda^2-x_1-x_2\\)。无穷远是单位。扭曲、小判别式、非素阶会掉进 Pohlig–Hellman 或 MOV 转移，选曲线要按标准。Shor 对 \\([k]P\\) 同样多项式，后量子不在 ECC 上续命。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证结合律，不引入除子、Weil 对。不选具体 NIST/Curve25519 当定义。后课默认：ECC 群是弦切 Abel 群，DLP 假设更强于大素数域。下一课格与 LWE。</p><p>弦切法给出 Abel 群，标量乘是快速幂。Hasse 管点数，阶要有大素因子。协议形状与 DH 相同，密钥更短。Shor 同样适用，故后量子不在这条曲线上找。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(E(\\mathbb{F}_q)\\) 弦切成 Abel 群；标量乘 = 快速幂。</li><li>Hasse 管点数；阶要有大素因子。</li><li>同形 DH，更短密钥；Shor 仍威胁。</li><li>出处：Silverman；Hankerson, Menezes and Vanstone。</li></ul>',7))])}const b=p(d,[["render",m]]);export{_ as __pageData,b as default};
